mapper.select:
SELECT MIN(r.id) as id, r.employee_id, r.att_date, MIN(r.shift_id) as shift_id, e.name as employee_name, e.employee_no, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, d.unit_name as dept_name, s.shift_name, SUM(COALESCE(r.late_minutes, 0)) as late_minutes, SUM(COALESCE(r.early_minutes, 0)) as early_minutes, SUM(COALESCE(r.work_hours, 0)) as work_hours, MAX(r.status) as status, MAX(COALESCE(r.locked, 0)) as locked, COALESCE(app.overtime_duration, 0) as overtime_duration, COALESCE(app.business_duration, 0) as business_duration, COALESCE(app.annual_leave_duration, 0) as annual_leave_duration, COALESCE(app.personal_leave_duration, 0) as personal_leave_duration, COALESCE(app.sick_leave_duration, 0) as sick_leave_duration, COALESCE(app.marriage_leave_duration, 0) as marriage_leave_duration, COALESCE(app.maternity_leave_duration, 0) as maternity_leave_duration, COALESCE(app.paternity_leave_duration, 0) as paternity_leave_duration, COALESCE(app.bereavement_leave_duration, 0) as bereavement_leave_duration FROM att_daily_record r LEFT JOIN hr_employee e ON r.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id LEFT JOIN org_unit p1 ON d.parent_id = p1.id LEFT JOIN org_unit p2 ON p1.parent_id = p2.id LEFT JOIN org_unit p3 ON p2.parent_id = p3.id LEFT JOIN att_shift s ON r.shift_id = s.id LEFT JOIN ( SELECT a.employee_id, DATE(a.start_time) as app_start, DATE(a.end_time) as app_end, SUM(CASE WHEN a.app_type = 'overtime' THEN a.duration ELSE 0 END) as overtime_duration, SUM(CASE WHEN a.app_type = 'business' THEN a.duration ELSE 0 END) as business_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '1' THEN a.duration ELSE 0 END) as annual_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '2' THEN a.duration ELSE 0 END) as personal_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '3' THEN a.duration ELSE 0 END) as sick_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '4' THEN a.duration ELSE 0 END) as marriage_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '5' THEN a.duration ELSE 0 END) as maternity_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '6' THEN a.duration ELSE 0 END) as paternity_leave_duration, SUM(CASE WHEN a.app_type = 'leave' AND a.title = '7' THEN a.duration ELSE 0 END) as bereavement_leave_duration FROM hr_application a WHERE a.status = 1 AND a.app_type IN ('overtime', 'business', 'leave') GROUP BY a.employee_id, DATE(a.start_time), DATE(a.end_time) ) app ON app.employee_id = r.employee_id AND app.app_start <= r.att_date AND app.app_end >= r.att_date
AND r.att_date >= #{startDate}
AND r.att_date <= #{endDate}
AND e.dept_id IN
#{orgId}
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND r.status = #{status}
GROUP BY r.employee_id, r.att_date, e.name, e.employee_no, d.unit_type, d.unit_name, p1.unit_type, p1.unit_name, p2.unit_type, p2.unit_name, p3.unit_type, p3.unit_name, s.shift_name, app.overtime_duration, app.business_duration, app.annual_leave_duration, app.personal_leave_duration, app.sick_leave_duration, app.marriage_leave_duration, app.maternity_leave_duration, app.paternity_leave_duration, app.bereavement_leave_duration ORDER BY r.att_date DESC, e.employee_no
